mapper.select:
SELECT t.*, s.name AS station_name, u.nickname AS audit_user_name
FROM fee_rule t
LEFT JOIN station_info s ON t.station_id = s.id
LEFT JOIN station_user u ON t.audit_user_id = u.id
WHERE t.deleted = 0

    AND t.station_id = #{pageReqVO.stationId}


    AND s.name LIKE CONCAT('%', #{pageReqVO.stationName}, '%')


    AND t.rate_type = #{pageReqVO.rateType}


    AND t.free_time BETWEEN #{pageReqVO.freeTime[0]} AND #{pageReqVO.freeTime[1]}


    AND t.charge_unit = #{pageReqVO.chargeUnit}


    AND t.status = #{pageReqVO.status}


    AND t.audit_time BETWEEN #{pageReqVO.auditTime[0]} AND #{pageReqVO.auditTime[1]}


    AND t.audit_user_id = #{pageReqVO.auditUserId}


    AND u.nickname LIKE CONCAT('%', #{pageReqVO.auditUserName}, '%')


    AND t.match_rate = #{pageReqVO.matchRate}


    AND t.first_hour_price = #{pageReqVO.firstHourPrice}


    AND t.step_price = #{pageReqVO.stepPrice}


    AND t.max_price = #{pageReqVO.maxPrice}


    AND t.peak_valley_config = #{pageReqVO.peakValleyConfig}


    AND t.member_config = #{pageReqVO.memberConfig}


    AND t.remark = #{pageReqVO.remark}


    AND t.reserve1 = #{pageReqVO.reserve1}


    AND t.reserve2 = #{pageReqVO.reserve2}


    AND t.creator = #{pageReqVO.creator}


    AND t.updater = #{pageReqVO.updater}


    AND t.create_time BETWEEN #{pageReqVO.createTime[0]} AND #{pageReqVO.createTime[1]}


    AND t.update_time BETWEEN #{pageReqVO.updateTime[0]} AND #{pageReqVO.updateTime[1]}

ORDER BY t.id DESC
